import {initUI,syncUI} from './ui.js';
import {renderMindMap} from './mindmap.js';
import {exact,scoreQuiz} from './logic.mjs';
import {renderLab,labList} from './labs.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const link=(href,text,cls='')=>`<a class="${cls}" href="${href}">${esc(text)}</a>`;
const KEY='architect-quest-v1';
const blank=()=>({read:[],recall:{},notes:{},correct:[],latest:{},history:[],labs:[],session:null,last:'l002',start:new Date().toISOString().slice(0,10)});
let localPdfUrl='',localPdfName='';
let state=blank(),storageOK=true,C,Q,G,R,M,lessonMap,questionMap,toastTimer;
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved&&Array.isArray(saved.read)&&typeof saved.notes==='object'){state={...blank(),...saved};}}catch{storageOK=false;}
function cleanState(raw){
 const clean=blank(),obj=v=>v&&typeof v==='object'&&!Array.isArray(v)?v:{},arr=v=>Array.isArray(v)?v:[],hasLesson=id=>typeof id==='string'&&Object.hasOwn(lessonMap,id),hasQuestion=id=>typeof id==='string'&&Object.hasOwn(questionMap,id);
 raw=obj(raw);clean.read=[...new Set(arr(raw.read).filter(hasLesson))];clean.correct=[...new Set(arr(raw.correct).filter(hasQuestion))];
 for(const [id,note]of Object.entries(obj(raw.notes)))if(hasLesson(id)&&typeof note==='string')clean.notes[id]=note;
 for(const [id,r]of Object.entries(obj(raw.recall)))if(hasLesson(id)&&r&&['explain','review'].includes(r.rating)&&Number.isFinite(r.due))clean.recall[id]={rating:r.rating,due:r.due,last:Number.isFinite(r.last)?r.last:0,streak:Number.isFinite(r.streak)?Math.max(0,Math.floor(r.streak)):0};
 for(const [id,r]of Object.entries(obj(raw.latest)))if(hasQuestion(id)&&r&&typeof r.correct==='boolean')clean.latest[id]={correct:r.correct,date:Number.isFinite(r.date)?r.date:0};
 clean.history=arr(raw.history).filter(h=>h&&Number.isInteger(h.total)&&h.total>0&&Number.isInteger(h.correct)&&h.correct>=0&&h.correct<=h.total&&Number.isFinite(h.date)).slice(-100).map(h=>({...h,percent:Math.round(h.correct/h.total*100),timed:!!h.timed}));
 clean.labs=[...new Set(arr(raw.labs).filter(id=>/^triage-[0-9]$/.test(id)))];if(hasLesson(raw.last))clean.last=raw.last;
 if(typeof raw.start==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(raw.start)&&Number.isFinite(Date.parse(raw.start+'T00:00:00Z')))clean.start=raw.start;
 const s=obj(raw.session),ids=arr(s.ids);
 if(ids.length&&ids.length<=Q.length&&new Set(ids).size===ids.length&&ids.every(hasQuestion)&&(!s.timed||Number.isFinite(s.deadline))){
  const order={},answers={},locked={};for(const id of ids){const indices=questionMap[id].options.map((_,i)=>i),savedOrder=obj(s.order)[id];order[id]=exact(savedOrder,indices)?savedOrder:indices;answers[id]=[...new Set(arr(obj(s.answers)[id]).filter(i=>Number.isInteger(i)&&indices.includes(i)))];locked[id]=!!obj(s.locked)[id]&&answers[id].length===questionMap[id].correct.length;}
  clean.session={...s,ids,order,answers,locked,index:Number.isInteger(s.index)?Math.min(ids.length-1,Math.max(0,s.index)):0,timed:!!s.timed,done:!!s.done};
 }
 return clean;
}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;toast('Browser storage unavailable. Export a progress backup from My notes before closing.');}updateXP();}
function xp(){return state.read.length*5+state.correct.length*30+Object.values(state.recall).filter(x=>x.rating==='explain').length*20+state.labs.length*10;}
function updateXP(){const x=$('#xp');if(x)x.textContent=xp().toLocaleString()+' XP';}
function toast(text){$('#toast').textContent=text;$('#toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),4200);}
function navigate(path){if(location.hash==='#'+path)render();else location.hash=path;}
function route(){return location.hash.replace(/^#/,'').split('/');}
function pageLesson(page){return C.lessons.find(l=>page>=l.start&&page<=l.end);}
function reviewed(id){return state.recall[id]?.rating==='explain';}
function recallDue(){return C.lessons.filter(l=>state.recall[l.id]&&(state.recall[l.id].rating==='review'||state.recall[l.id].due<=Date.now()));}
function gradeRecall(id,rating){if(!lessonMap[id])return;const old=state.recall[id];const streak=rating==='explain'?(old?.streak||0)+1:0;state.recall[id]={rating,streak,last:Date.now(),due:Date.now()+(rating==='explain'?Math.min(4,2**(streak-1))*86400000:0)};save();toast(rating==='explain'?'Self-rated recall saved. Revisit after a delay to test retention.':'Added to your recall review queue.');render();}
function markRead(id){if(!lessonMap[id])return;if(!state.read.includes(id)){state.read.push(id);save();toast('Read ✓ +5 XP. Now close the notes and explain the mechanism.');render();}}
function home(){const last=lessonMap[state.last]||C.lessons[1],due=recallDue(),read=state.read.length,recall=Object.values(state.recall).filter(x=>x.rating==='explain').length;$('#app').innerHTML=shell(`<section class="desk-hero"><div class="desk-intro"><p class="section-context">Your bilingual architecture studio</p><h1>Understand deeply.<br><em>Decide confidently.</em></h1><p class="desk-lede">Satu konsep, satu alasan yang jelas. Build your mental model, test it in a scenario, then explain it without the notes.</p><a class="button primary desk-continue" href="#learn/${last.id}">Continue learning <span aria-hidden="true">→</span></a><p class="desk-last">Pick up at <a href="#learn/${last.id}">${esc(last.title)}</a></p></div><aside class="desk-plan"><div class="desk-plan-top"><span>YOUR NEXT SESSION</span><a href="#route">Full route →</a></div><h2>A little structure.<br>A clearer mind.</h2><ol class="session-steps"><li><span>01</span><div><a href="#notes">Retrieve yesterday’s ideas</a><p>${due.length?due.length+' lessons are due for recall.':'Explain one mechanism before opening the notes.'}</p></div></li><li><span>02</span><div><a href="#learn/${last.id}">Learn one mechanism</a><p>Read, compare, and write your reasoning.</p></div></li><li><span>03</span><div><a href="#practice/setup">Apply it in a scenario</a><p>Say why the closest alternative fails.</p></div></li></ol><div class="desk-progress">${progressBar(read,101,'Lessons read')}<p>${recall} self-rated explainable · ${due.length} due for review</p></div></aside></section><section class="desk-tools"><div class="desk-section-head"><h2>Your ways into the material.</h2><p>Choose the tool that answers today’s question.</p></div><div class="desk-tool-grid"><a class="desk-tool map-tool" href="#mindmap"><svg class="desk-map-mark" viewBox="0 0 280 80" aria-hidden="true"><path d="M138 40H68M68 40V15H18M68 40v25H18M142 40h70m0 0V15h50m-50 25v25h50"/><circle cx="140" cy="40" r="17"/><circle cx="18" cy="15" r="5"/><circle cx="18" cy="65" r="5"/><circle cx="262" cy="15" r="5"/><circle cx="262" cy="65" r="5"/></svg><span class="desk-tool-meta">176 services & features</span><h3>See the connections.</h3><p>Explore the service mind map, then hide the names and test your memory.</p><span class="text-action">Open the service map <b aria-hidden="true">↗</b></span></a><a class="desk-tool" href="#labs/iam"><span class="desk-tool-meta">6 interactive labs</span><h3>Change it. Understand it.</h3><p>Trace permissions, network paths, capacity, caching, and recovery.</p><span class="text-action">Try a lab <b aria-hidden="true">↗</b></span></a><a class="desk-tool" href="#reference"><span class="desk-tool-meta">14 comparison tables</span><h3>Find the deciding detail.</h3><p>Separate similar services by the requirement that changes the answer.</p><span class="text-action">Compare alternatives <b aria-hidden="true">↗</b></span></a></div></section><footer class="desk-footer"><p>101 lessons · 332 terms · 75 original practice scenarios</p><p>Your notes and progress stay in this browser. <a href="#notes">Manage your backup →</a></p><p>Read ≠ remembered. XP supports practice; it does not predict an exam score.</p></footer>`);}
function shell(content,sidebar=''){return `<div class="workspace ${sidebar?'with-sidebar':''}">${sidebar?`<aside class="sidebar"><button class="lesson-nav-toggle" aria-expanded="false" aria-controls="lesson-browser-content">Browse the 101 lessons <span aria-hidden="true">+</span></button><div id="lesson-browser-content">${sidebar}</div></aside>`:''}<main id="main" tabindex="-1">${content}</main></div>`;}
function sectionLabel(over,title,desc=''){return `<p class="section-context">${over}</p><h1>${title}</h1>${desc?`<p class="lede">${desc}</p>`:''}`;}
function progressBar(value,max,label){return `<div class="progress-line"><span>${esc(label)}</span><b>${value}/${max}</b></div><div class="progress-track" role="progressbar" aria-label="${esc(label)}" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="${max}"><i style="transform:scaleX(${max?value/max:0})"></i></div>`;}
function chapterSidebar(l){return `<div class="sidebar-top"><div class="eyebrow">THE COMPLETE COURSE</div><h2>Build your mental model.</h2><p>828 slides → 101 decision lessons</p><label class="search-label"><span class="sr-only">Search lessons</span><input id="lesson-search" type="search" placeholder="Search a service or concept…"></label><div id="lesson-search-results"></div></div><div class="chapter-list">${C.chapters.map(ch=>{const list=C.lessons.filter(x=>x.chapter===ch.id);return `<details ${ch.id===l.chapter?'open':''}><summary><span class="chapter-number">${String(ch.id).padStart(2,'0')}</span><span>${esc(ch.title)}<small>${list.filter(x=>state.read.includes(x.id)).length}/${list.length} read · slides ${ch.start}–${ch.end}</small></span></summary><div class="lesson-links">${list.map(x=>`<a href="#learn/${x.id}" ${x.id===l.id?'aria-current="page"':''}><span class="lesson-status ${reviewed(x.id)?'recall':state.read.includes(x.id)?'read':''}">${reviewed(x.id)?'✓':state.read.includes(x.id)?'·':''}</span>${esc(x.title)}</a>`).join('')}</div></details>`;}).join('')}</div><div class="sidebar-bottom">${progressBar(state.read.length,C.lessons.length,'Lessons read')}<p>Read ≠ remembered.<br>Self-rated recall: ${Object.values(state.recall).filter(x=>x.rating==='explain').length}/101</p><a href="#notes">${recallDue().length} due for recall review →</a></div>`;}
function updateCard(u,compact=false){return `<div class="update-card ${compact?'compact':''}"><span class="tag">CURRENT AWS NOTE</span><h3>${esc(u.title)}</h3><p>${esc(u.note)}</p><a href="${esc(u.url)}" target="_blank" rel="noopener">AWS documentation ↗</a><small>Related PDF pages: ${u.pages.join(', ')}</small></div>`;}
function learn(id){const l=lessonMap[id]||C.lessons[0];state.last=l.id;save();const ch=C.chapters[l.chapter],idx=C.lessons.indexOf(l),updates=R.updates.filter(u=>u.pages.some(p=>p>=l.start&&p<=l.end));const terms=G.filter(g=>g.term.length>2&&new RegExp('(^|[^a-z])'+g.term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'([^a-z]|$)','i').test([l.title,l.mental,...l.core].join(' '))).slice(0,9);
 const content=`<div class="lesson-top"><span class="eyebrow">DAY ${l.day} · ${esc(ch.title)}</span><span class="fine">${idx+1}/101 · ~${l.minutes} min + recall</span></div><h1>${esc(l.title)}</h1><div class="source-row"><a href="#source/${l.start}">Source slides ${l.start}–${l.end} ↗</a><span>EN concepts · ID mental model</span></div><div class="reading-grid"><article class="lesson-body"><div class="bridge"><span class="eyebrow">PAHAMI DULU · THE MENTAL MODEL</span><p>${esc(l.mental)}</p></div><h2>How it works</h2><div class="core">${l.core.map((p,i)=>`<div class="core-step"><span>${String(i+1).padStart(2,'0')}</span><p>${esc(p)}</p></div>`).join('')}</div><div class="decision-box"><span class="eyebrow">THE ARCHITECT’S DECISION</span><p>${esc(l.decision)}</p></div><h2>A concrete example</h2><p>${esc(l.example)}</p><div class="trap"><span class="eyebrow">EXAM TRAP · JANGAN TERKECOH</span><p>${esc(l.trap)}</p></div>${terms.length?`<section class="inline-glossary"><h2>Decode the jargon</h2><p class="fine">Open a term to connect the name to its meaning.</p>${terms.map(g=>`<details><summary>${esc(g.term)} <small>${esc(g.expansion)}</small></summary><p lang="id">${esc(g.definition)}</p></details>`).join('')}<a href="#glossary">Explore all 332 terms →</a></section>`:''}${updates.map(u=>updateCard(u,true)).join('')}<div class="source-preview panel"><h2>Connect this lesson to your PDF</h2><p>Open your own course PDF locally to inspect diagrams on pages ${l.start}–${l.end}. The file stays in your browser.</p><a class="button" href="#source/${l.start}">Open my PDF at page ${l.start} →</a></div><div class="lesson-actions"><button id="mark-read" class="primary" ${state.read.includes(l.id)?'disabled':''}>${state.read.includes(l.id)?'✓ Marked read':'Mark as read · +5 XP'}</button><a href="#practice/chapter-${l.chapter}" class="button">Practice this topic →</a></div><nav class="lesson-pager" aria-label="Lesson navigation">${idx?link('#learn/'+C.lessons[idx-1].id,'← '+C.lessons[idx-1].title):'<span></span>'}${idx<C.lessons.length-1?link('#learn/'+C.lessons[idx+1].id,C.lessons[idx+1].title+' →'):link('#route','Review your study route →')}</nav></article><aside class="study-rail"><section class="recall-card"><span class="eyebrow">CLOSE THE NOTES. RETRIEVE.</span><h2>Can you explain it?</h2><p class="recall-question">${esc(l.question)}</p><p class="fine">Jawab aloud first. Use your own words; explain why an alternative fails.</p><details id="recall-answer"><summary>Reveal the reasoning</summary><p>${esc(l.answer)}</p><div class="recall-buttons"><button data-recall="review">Need review</button><button data-recall="explain" class="primary">Can explain</button></div></details><p class="fine">${state.recall[l.id]?`Your last self-rating: <b>${state.recall[l.id].rating==='explain'?'can explain':'needs review'}</b>.`:'Self-rating tracks recall confidence, not an exam result.'}</p></section><section class="notes-card"><label for="lesson-note"><h2>My notes <span>✎</span></h2></label><p class="fine">Use both languages. Tulis alasan, bukan hanya nama service.</p><textarea id="lesson-note" rows="8" placeholder="Decisive constraint:\nWhy this design works:\nWhy the alternative fails:\nWhat I still confuse:">${esc(state.notes[l.id]||'')}</textarea><span class="save-status" id="note-status">${storageOK?'Saved on this browser/device':'Browser storage unavailable'}</span></section><a class="rail-link" href="#labs/${C.days.find(d=>d.day===l.day)?.lab||'iam'}"><span>TRY THE MECHANISM</span>Open today’s lab ↗</a></aside></div>`;
 $('#app').innerHTML=shell(content,chapterSidebar(l));$('#mark-read').onclick=()=>markRead(l.id);document.querySelectorAll('[data-recall]').forEach(b=>b.onclick=()=>gradeRecall(l.id,b.dataset.recall));$('#lesson-note').oninput=e=>{state.notes[l.id]=e.target.value;save();$('#note-status').textContent=storageOK?'Saved on this browser/device':'Storage unavailable — export before closing';};$('#lesson-search').oninput=e=>{const text=e.target.value.toLowerCase().trim();$('#lesson-search-results').innerHTML=text?`<div class="search-results">${C.lessons.filter(x=>[x.title,x.mental,...x.core,x.decision,x.trap].join(' ').toLowerCase().includes(text)).slice(0,25).map(x=>link('#learn/'+x.id,x.title)).join('')||'<p>No lesson match. Try a service name.</p>'}</div>`:'';};
}
function studyRoute(){const elapsed=Math.max(1,Math.floor((Date.now()-new Date(state.start+'T00:00:00').getTime())/86400000)+1);const due=recallDue();$('#app').innerHTML=shell(`${sectionLabel('7 DAYS TO COVER · 3½ DAYS TO CONSOLIDATE','Your route to understanding.','Belajar bukan scrolling. Read → explain → apply → revisit. This intensive plan assumes roughly 4–6 focused hours per learning day; move unfinished lessons forward if you have less time.')}<div class="route-banner"><div><strong>Today: study day ${Math.min(elapsed,11)}</strong><p>${state.read.length}/101 read · ${due.length} recall reviews due · ${Object.values(state.latest).filter(v=>!v.correct).length} practice mistakes to repair</p></div><label class="field">My study start date<input id="start-date" type="date" value="${esc(state.start)}"></label></div><div class="protocol"><div><b>01</b><strong>Retrieve · 20 min</strong><p>Yesterday’s concepts without notes.</p></div><div><b>02</b><strong>Learn · 3 × 50 min</strong><p>Read lessons and inspect diagrams. Take breaks.</p></div><div><b>03</b><strong>Apply · 45–60 min</strong><p>Lab + scenarios. Explain distractors.</p></div><div><b>04</b><strong>Repair · 30–45 min</strong><p>Write mistakes; schedule recall. Add time for dense topics.</p></div></div><div class="day-list">${C.days.map(d=>{const list=d.lessonIds.map(id=>lessonMap[id]);return `<details class="day-card" ${d.day===Math.min(elapsed,11)?'open':''}><summary><span class="day-number">${String(d.day).padStart(2,'0')}</span><span><small>${d.day<=7?'LEARN & APPLY':d.day===11?'FINAL HALF-DAY':'CONSOLIDATE'}</small><strong>${esc(d.title)}</strong><span>${esc(d.hours)}${list.length?' · '+list.length+' lessons':''}</span></span><span class="day-count">${list.length?list.filter(l=>state.read.includes(l.id)).length+'/'+list.length:'→'}</span></summary><div class="day-content"><p class="bridge">${esc(d.mission)}</p><p>${esc(d.focus)}</p><div class="deliverable"><strong>Produce this · Hasil hari ini</strong><p>${esc(d.deliverable)}</p></div>${list.length?`<div class="day-lessons">${list.map(l=>`<a href="#learn/${l.id}"><span>${state.read.includes(l.id)?'✓':'○'}</span>${esc(l.title)}<small>${l.start}–${l.end}</small></a>`).join('')}</div>`:''}<div class="button-row">${d.lab?link('#labs/'+d.lab,'Open the lab','button primary'):link(d.day===9?'#practice/setup':'#notes','Open revision tools','button primary')}${link('#practice/setup','Practice scenarios →','button')}</div></div></details>`;}).join('')}</div><section class="panel exam-frame"><h2>Know what the score means</h2><p>The SAP-C02 baseline is 75 questions in 180 minutes: 65 scored and 10 unscored. AWS reports a scaled score of 100–1,000 with a 750 passing score; <strong>750 is not “75% correct.”</strong> All questions here contribute to your local learning score. These original questions are study practice, not official AWS exam items.</p><div class="domain-bars">${C.domains.map(d=>`<div><span>D${d.id} · ${esc(d.title)}</span><div class="bar-track"><i style="width:${d.weight}%"></i></div><b>${d.weight}%</b></div>`).join('')}</div><p>For multiple-response items, choose the stated number. There is no penalty for guessing on the official exam; manage time and answer every item.</p><p>${R.examSources.map(s=>`<a target="_blank" rel="noopener" href="${s.url}">${esc(s.title)} ↗</a>`).join(' · ')}</p><p class="fine">If your exam is about 1½ weeks away, use Days 8–10 for weak areas and a fresh official practice assessment, then keep the last half-day light. XP is motivation, not proof of readiness.</p></section>`);$('#start-date').onchange=e=>{if(e.target.value){state.start=e.target.value;save();studyRoute();}};}
function glossary(){const draw=term=>{const rows=G.filter(g=>[g.term,g.expansion,g.definition].join(' ').toLowerCase().includes(term.toLowerCase()));$('#glossary-count').textContent=rows.length+' terms';$('#glossary-grid').innerHTML=rows.map(g=>`<article class="glossary-card"><h2>${esc(g.term)}</h2><span>${esc(g.expansion)}</span><p lang="id">${esc(g.definition)}</p></article>`).join('')||'<p>No match. Try the abbreviation or its English expansion.</p>';};$('#app').innerHTML=shell(`${sectionLabel('332 TERMS · ENGLISH NAME, BAHASA MEANING','Decode the language of architecture.','Keep the English service name for the exam. Gunakan Bahasa untuk memahami mekanismenya. Similar words do not always describe the same guarantee.')}<div class="filter-bar"><label class="search-label grow"><span class="sr-only">Search jargon</span><input type="search" id="glossary-search" placeholder="Try RPO, idempotency, federation, shard…"></label><span id="glossary-count"></span></div><div class="glossary-grid" id="glossary-grid"></div>`);$('#glossary-search').oninput=e=>draw(e.target.value);draw('');}
function references(){const draw=text=>{$('#reference-tables').innerHTML=R.tables.filter(t=>JSON.stringify(t).toLowerCase().includes(text.toLowerCase())).map(t=>`<details class="comparison" ${text?'open':''}><summary>${esc(t.title)}<small>Slides ${t.pages[0]}–${t.pages[1]}</small></summary><div class="table-scroll"><table><thead><tr>${t.headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${t.rows.map(r=>`<tr>${r.map((c,i)=>i?`<td>${esc(c)}</td>`:`<th scope="row">${esc(c)}</th>`).join('')}</tr>`).join('')}</tbody></table></div><p>${esc(t.note)}</p><a href="#source/${t.pages[0]}">Inspect source slides →</a></details>`).join('');};$('#app').innerHTML=shell(`${sectionLabel('COMPARE THE CLOSEST ALTERNATIVES','Choose by constraint.','The exam often tests two plausible designs. Find the requirement that makes one a better fit. Cari pembeda, bukan keyword tunggal.')}<label class="search-label"><span class="sr-only">Search comparison tables</span><input id="table-search" type="search" placeholder="Search comparisons: storage, IAM, migration…"></label><div id="reference-tables"></div><section class="updates-section"><div class="eyebrow">16 CORRECTIONS & CLARIFICATIONS · CHECKED ${R.updated}</div><h2>Read the slides with current context.</h2><p>The v38 deck contains older limits and simplifications. These notes correct selected material differences using AWS documentation. This is not a line-by-line audit of every quota or historical price. Untuk exam, understand the design requirement and distinguish defaults from hard limits.</p><div class="updates-grid">${R.updates.map(u=>updateCard(u)).join('')}</div></section><section class="panel"><h2>Your source and coverage</h2><p>Based on all 828 pages of <em>${esc(C.source)}</em>, by ${esc(C.author)}. The 101 original bilingual lessons group the material into decisions and mechanisms; the local PDF reader lets you consult your own copy at the referenced page. The public website does not distribute the original deck. Administrative and closing pages are included in the lesson coverage.</p><p>This is an independent personal study companion, not an AWS or author-endorsed course. The practice bank contains original scenarios; it is not an exam dump.</p>${R.examSources.map(s=>`<p><a href="${s.url}" target="_blank" rel="noopener">${esc(s.title)} ↗</a></p>`).join('')}</section>`);$('#table-search').oninput=e=>draw(e.target.value);draw('');}
function source(page){
 page=Math.min(828,Math.max(1,Math.floor(Number(page))||1));const l=pageLesson(page);
 $('#app').innerHTML=shell(`${sectionLabel('YOUR LOCAL PDF · 828-PAGE COURSE REFERENCE','The source desk.','Pilih PDF milikmu untuk membaca diagram aslinya. The file opens only in this browser; it is not uploaded. Page references match the 828-page v38 course PDF.')}<div class="source-local-upload panel"><label class="field">${localPdfUrl?'Change PDF':'Choose your course PDF'}<input id="local-pdf" type="file" accept="application/pdf,.pdf"></label><p class="local-pdf-note">${localPdfUrl?`Selected: <b>${esc(localPdfName)}</b>.`:'Use your own copy of the course slides.'} Select it again after refreshing the website. A different edition may have different page numbers.</p><p id="pdf-error" role="status"></p></div><div class="source-tools"><a class="button" href="#source/${Math.max(1,page-1)}" aria-label="Previous slide">←</a><label class="field inline-field">Page<input id="source-page" type="number" min="1" max="828" value="${page}"> / 828</label><button id="source-go" class="button">Go</button><a class="button" href="#source/${Math.min(828,page+1)}" aria-label="Next slide">→</a><a class="button primary" href="#learn/${l.id}">Explain this · ${esc(l.title)} →</a></div>${localPdfUrl?`<p class="fine">Use your browser PDF controls to search and zoom. If the embedded reader does not display or jump to the page, <a href="${localPdfUrl}#page=${page}" target="_blank" rel="noopener">open your PDF in a new tab ↗</a> and enter page ${page}.</p><iframe class="local-pdf-frame" src="${localPdfUrl}#page=${page}" title="Your local course PDF, requested page ${page}"></iframe>`:`<div class="empty"><h2>Your PDF will appear here.</h2><p>The public lessons and mind map work without a PDF. Choose your file above to inspect the original source.</p><a href="#mindmap">Explore the service mind map →</a></div>`}${R.updates.filter(u=>u.pages.includes(page)).map(u=>updateCard(u,true)).join('')}`);
 const jump=()=>navigate('source/'+Math.min(828,Math.max(1,Math.floor(Number($('#source-page').value))||1)));
 $('#source-go').onclick=jump;$('#source-page').onkeydown=e=>{if(e.key==='Enter')jump();};
 $('#local-pdf').onchange=e=>{const file=e.target.files?.[0];if(!file)return;if(!file.size||(!/\.pdf$/i.test(file.name)&&file.type!=='application/pdf')){$('#pdf-error').textContent='Please choose a non-empty PDF file.';return;}if(localPdfUrl)URL.revokeObjectURL(localPdfUrl);localPdfUrl=URL.createObjectURL(file);localPdfName=file.name;source(page);};
}
function notes(){const due=recallDue(),mistakes=Q.filter(q=>state.latest[q.id]&&!state.latest[q.id].correct),notes=C.lessons.filter(l=>state.notes[l.id]?.trim());$('#app').innerHTML=shell(`${sectionLabel('YOUR RETRIEVAL & REPAIR DESK','Turn mistakes into decisions.','Kesalahan adalah petunjuk: knowledge gap, missed constraint, confused guarantee, or rushing. Record what changed your answer.')}<div class="stats-row"><div><b>${state.read.length}<small>/101</small></b><span>lessons read</span></div><div><b>${due.length}</b><span>recall reviews due</span></div><div><b>${mistakes.length}</b><span>latest practice mistakes</span></div><div><b>${notes.length}</b><span>lessons with notes</span></div></div><div class="notes-toolbar"><p>${storageOK?'Progress and notes are saved on this browser/device. They do not sync across devices. Importing a backup replaces current progress and notes.':'Browser storage is unavailable. Export a backup before closing.'}</p><button id="export-progress" class="button">Export progress backup</button><label class="button import-label">Import backup<input type="file" id="import-progress" accept="application/json,.json"></label></div><div class="review-columns"><section class="panel"><h2>Recall queue</h2><p class="fine">“Need review” stays here. “Can explain” returns after 1, 2, then up to 4 days. These are self-ratings.</p>${due.length?due.map(l=>`<a class="queue-item" href="#learn/${l.id}"><strong>${esc(l.title)}</strong><small>${state.recall[l.id].rating==='review'?'Needs review':'Spaced recall due'} · Day ${l.day}</small></a>`).join(''):'<p>No recall reviews due. Reveal a lesson’s recall answer and rate your explanation to start.</p>'}</section><section class="panel"><h2>Practice repair queue</h2>${mistakes.length?`${link('#practice/mistakes','Practice these mistakes','button primary')} ${mistakes.map(q=>`<a class="queue-item" href="#learn/${pageLesson(q.page).id}"><strong>${esc(q.stem)}</strong><small>Review mechanism · source page ${q.page}</small></a>`).join('')}`:'<p>No recorded mistakes yet. A completed practice answer adds weak areas here.</p>'+link('#practice/setup','Start practice →','button')}</section></div><section><h2>Your lesson notes</h2>${notes.length?notes.map(l=>`<article class="panel saved-note"><a href="#learn/${l.id}"><h3>${esc(l.title)} ↗</h3></a><p>${esc(state.notes[l.id])}</p></article>`).join(''):'<div class="empty"><h3>Your decision journal starts in any lesson.</h3><p>Write the decisive constraint, why the chosen design fits, and why the tempting alternative fails.</p></div>'}</section><section class="panel"><h2>Practice history</h2>${state.history.length?`<div class="table-scroll"><table><thead><tr><th>Completed</th><th>Mode</th><th>Learning score</th></tr></thead><tbody>${state.history.slice().reverse().map(h=>`<tr><td>${esc(new Date(h.date).toLocaleString())}</td><td>${h.timed?'Timed':'Learning'}</td><td>${h.correct}/${h.total} · ${h.percent}%</td></tr>`).join('')}</tbody></table></div>`:'<p>Completed sessions will appear here.</p>'}</section>`);$('#export-progress').onclick=()=>{const blob=new Blob([JSON.stringify({format:'architect-quest-v1',exported:new Date().toISOString(),state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='architect-quest-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('#import-progress').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>5000000)throw Error('File too large');const v=JSON.parse(await f.text());if(v.format!=='architect-quest-v1'||!v.state||!Array.isArray(v.state.read)||typeof v.state.notes!=='object')throw Error('Not a valid Architect Quest backup');const clean=cleanState(v.state);clean.session=null;state=clean;save();toast('Backup imported. Completed progress restored; active quiz starts fresh.');notes();}catch(err){toast('Import failed: '+err.message);}};}
function labs(id){const selected=labList.some(l=>l[0]===id)?id:'iam';$('#app').innerHTML=shell(`<nav class="lab-tabs" aria-label="Architecture labs">${labList.map(l=>`<a href="#labs/${l[0]}" ${l[0]===selected?'aria-current="page"':''}><span>${l[1]}</span><strong>${l[2]}</strong><small>${l[3]}</small></a>`).join('')}</nav><div id="lab-content"></div>`);renderLab($('#lab-content'),selected,key=>{if(!state.labs.includes(key)){state.labs.push(key);save();toast('Case solved · +10 XP');}});}
const shuffle=arr=>{const a=[...arr];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
function questionPool(filter){if(filter==='mistakes')return Q.filter(q=>state.latest[q.id]&&!state.latest[q.id].correct);if(filter?.startsWith('chapter-'))return Q.filter(q=>q.chapter===Number(filter.slice(8)));if(filter?.startsWith('domain-'))return Q.filter(q=>q.domain===Number(filter.slice(7)));return Q;}
function quizSetup(filter='all'){const pool=questionPool(filter);$('#app').innerHTML=shell(`${sectionLabel('75 ORIGINAL SCENARIOS · EXPLAIN EVERY OPTION','Practice the decision, not the keyword.','Learning mode reveals the reasoning after each answer. Timed mode holds feedback until you finish. Multiple-response questions require the exact set; tidak ada partial credit.')}<div class="practice-layout"><section class="panel practice-config"><h2>Set your session</h2><label class="field">Question pool<select id="quiz-filter"><option value="all">All topics · 75 questions</option><option value="mistakes">My latest mistakes</option>${C.domains.map(d=>`<option value="domain-${d.id}">Domain ${d.id}: ${esc(d.title)}</option>`).join('')}${C.chapters.filter(c=>Q.some(q=>q.chapter===c.id)).map(c=>`<option value="chapter-${c.id}">${esc(c.title)}</option>`).join('')}</select></label><label class="field">Session length<select id="quiz-count"><option value="10">10 questions</option><option value="25">25 questions</option><option value="75">75 questions</option></select></label><label class="check"><input id="quiz-timed" type="checkbox">Timed mode · 2.4 minutes per question</label><p id="pool-size" class="fine">${pool.length} available. Smaller pools use all available questions.</p><button id="start-quiz" class="primary" ${!pool.length?'disabled':''}>Start session →</button>${state.session&&!state.session.done?`<div class="resume"><strong>You have an unfinished session.</strong><p>${Object.keys(state.session.answers).length}/${state.session.ids.length} answered${state.session.timed?' · timer continues while away':''}.</p><a href="#practice/session" class="button">Resume session</a><p class="fine">Starting another session replaces the unfinished one.</p></div>`:''}</section><aside><section class="panel"><span class="eyebrow">THE 4-PASS QUESTION ROUTINE</span><ol class="routine"><li><strong>Outcome</strong><p>What must improve: cost, recovery, latency, operations?</p></li><li><strong>Constraints</strong><p>Underline “must,” “least,” “without,” protocol, scale and migration restrictions.</p></li><li><strong>Eliminate</strong><p>Reject a design that violates even one required constraint.</p></li><li><strong>Compare</strong><p>Explain the remaining trade-off and select the best fit.</p></li></ol></section><p class="fine">All items are original educational practice, not official AWS items. Repeated-question scores can reflect familiarity. Use a fresh official assessment near exam day to identify remaining gaps.</p></aside></div>`);$('#quiz-filter').value=pool.length||filter==='mistakes'?filter:'all';const refresh=()=>{const n=questionPool($('#quiz-filter').value).length;$('#pool-size').textContent=`${n} available. Smaller pools use all available questions.`;$('#start-quiz').disabled=!n;};$('#quiz-filter').onchange=refresh;refresh();$('#start-quiz').onclick=()=>{const list=shuffle(questionPool($('#quiz-filter').value)).slice(0,Number($('#quiz-count').value));if(!list.length)return;const timed=$('#quiz-timed').checked;state.session={ids:list.map(q=>q.id),order:Object.fromEntries(list.map(q=>[q.id,shuffle(q.options.map((_,i)=>i))])),answers:{},locked:{},index:0,timed,deadline:timed?Date.now()+list.length*144000:null,started:Date.now(),done:false};save();navigate('practice/session');};}
function recordAnswer(q,answers){const ok=exact(answers||[],q.correct);state.latest[q.id]={correct:ok,date:Date.now()};if(ok&&!state.correct.includes(q.id))state.correct.push(q.id);return ok;}
function finishQuiz(expired=false){const s=state.session;if(!s||s.done)return;s.ids.forEach(id=>recordAnswer(questionMap[id],s.answers[id]||[]));s.done=true;s.expired=expired;s.finished=Date.now();const score=scoreQuiz(s,Q);state.history.push({...score,date:s.finished,timed:s.timed});state.history=state.history.slice(-100);save();if(route()[0]==='practice')navigate('practice/results');else toast('Timed session ended. Open Practice to review your results.');}
function explanation(q,chosen){return `<div class="answer-review"><div class="result ${exact(chosen||[],q.correct)?'pass':'fail'}"><strong>${exact(chosen||[],q.correct)?'Correct · Tepat':'Review this mechanism · Perlu review'}</strong><p>Correct selection: ${q.correct.map(i=>esc(q.options[i])).join(' + ')}</p></div>${q.options.map((v,i)=>`<div class="why-option ${q.correct.includes(i)?'right':''}"><span>${q.correct.includes(i)?'✓':'×'}</span><div><strong>${esc(v)}</strong>${chosen?.includes(i)?'<small class="tag">YOUR CHOICE</small>':''}<p>${esc(q.why[i])}</p></div></div>`).join('')}<div class="bridge"><strong>Hubungkan ke konsep</strong><p>${esc(pageLesson(q.page).mental)}</p></div><a href="#learn/${pageLesson(q.page).id}">Review the bilingual lesson →</a> · <a href="#source/${q.page}">Source slide ${q.page} →</a></div>`;}
function quizSession(){const s=state.session;if(!s)return quizSetup();if(s.done)return quizResults();if(s.timed&&s.deadline<=Date.now()){finishQuiz(true);return;}const q=questionMap[s.ids[s.index]],selected=s.answers[q.id]||[],locked=!s.timed&&s.locked[q.id];$('#app').innerHTML=shell(`<div class="quiz-top"><div><div class="eyebrow">${s.timed?'TIMED · FEEDBACK AT THE END':'LEARNING · IMMEDIATE FEEDBACK'}</div><h1>One constraint changes the answer.</h1></div><div class="quiz-timer" id="quiz-timer">${s.timed?'…':'Untimed'}</div></div><div class="quiz-layout"><section class="panel question-card"><div class="question-meta"><span>QUESTION ${s.index+1} / ${s.ids.length}</span><span>Domain ${q.domain} · ${q.correct.length>1?'Choose '+q.correct.length:'Choose one'}</span></div><h2>${esc(q.stem)}</h2><p class="fine">${q.correct.length>1?'Pilih tepat '+q.correct.length+' jawaban. All correct options are required.':'Pilih jawaban terbaik untuk constraint yang diberikan.'}</p><fieldset class="option-list"><legend class="sr-only">Answer choices</legend>${s.order[q.id].map((original,i)=>`<label class="option ${selected.includes(original)?'selected':''} ${locked&&q.correct.includes(original)?'correct':''}"><input type="${q.correct.length>1?'checkbox':'radio'}" name="answer" value="${original}" ${selected.includes(original)?'checked':''} ${locked?'disabled':''}><span>${String.fromCharCode(65+i)}</span><strong>${esc(q.options[original])}</strong></label>`).join('')}</fieldset><div class="question-actions">${!s.timed?`<button id="check-answer" class="primary" ${locked||selected.length!==q.correct.length?'disabled':''}>${locked?'Answer checked':'Check answer'}</button>`:'<span class="fine">Selections save automatically. You can revise until finishing.</span>'}<span id="selection-count" class="fine">${selected.length}/${q.correct.length} selected</span></div>${locked?explanation(q,selected):''}<div class="question-nav"><button id="prev-question" class="button" ${s.index===0?'disabled':''}>← Previous</button><button id="next-question" class="button" ${s.index===s.ids.length-1?'disabled':''}>Next →</button></div></section><aside class="panel quiz-map"><h2>Question map</h2><p class="fine">Filled = answered. In learning mode, ✓/× = checked.</p><div class="question-dots">${s.ids.map((id,i)=>`<button data-index="${i}" class="${i===s.index?'active':''} ${(s.answers[id]||[]).length?'answered':''}" aria-label="Question ${i+1}${s.answers[id]?.length?', answered':''}">${!s.timed&&s.locked[id]?(exact(s.answers[id],questionMap[id].correct)?'✓':'×'):i+1}</button>`).join('')}</div><p id="answered-total">${Object.values(s.answers).filter(a=>a.length).length}/${s.ids.length} with a selection</p><button id="finish-quiz" class="primary">Finish & review</button><p class="fine">Unanswered or incomplete selections count as incorrect. No partial credit. Leaving this tab does not pause a timed session.</p></aside></div>`);
 document.querySelectorAll('input[name="answer"]').forEach(input=>input.onchange=()=>{if(s.done||(!s.timed&&s.locked[q.id]))return;if(s.timed&&s.deadline<=Date.now()){finishQuiz(true);return;}const answers=[...document.querySelectorAll('input[name="answer"]:checked')].map(i=>Number(i.value));s.answers[q.id]=answers;save();document.querySelectorAll('.option').forEach(l=>l.classList.toggle('selected',l.querySelector('input').checked));$('#selection-count').textContent=answers.length+'/'+q.correct.length+' selected';const check=$('#check-answer');if(check)check.disabled=answers.length!==q.correct.length;$('#answered-total').textContent=Object.values(s.answers).filter(a=>a.length).length+'/'+s.ids.length+' with a selection';$(`[data-index="${s.index}"]`).classList.toggle('answered',!!answers.length);});if($('#check-answer'))$('#check-answer').onclick=()=>{if(s.locked[q.id]||(s.answers[q.id]||[]).length!==q.correct.length)return;s.locked[q.id]=true;recordAnswer(q,s.answers[q.id]);save();quizSession();};const jump=i=>{s.index=i;save();quizSession();$('#main').focus();};$('#prev-question').onclick=()=>jump(Math.max(0,s.index-1));$('#next-question').onclick=()=>jump(Math.min(s.ids.length-1,s.index+1));document.querySelectorAll('[data-index]').forEach(b=>b.onclick=()=>jump(Number(b.dataset.index)));$('#finish-quiz').onclick=()=>finishQuiz();tick();}
function quizResults(){const s=state.session;if(!s||!s.done)return quizSetup();const score=scoreQuiz(s,Q);$('#app').innerHTML=shell(`${sectionLabel('SESSION COMPLETE · USE THE REASONING TO IMPROVE','Debrief before the next attempt.','Review every incorrect or uncertain choice. Tulis constraint yang kamu lewatkan, lalu jelaskan jawaban dengan kata-katamu sendiri.')}<div class="result-hero"><div class="score-ring" style="--score:${score.percent}%"><span>${score.percent}<small>%</small></span></div><div><h2>${score.correct} / ${score.total} correct</h2><p>Local learning score · ${s.timed?'timed':'untimed'}${s.expired?' · time expired':''}</p><p class="fine">This percentage is not an AWS scaled score and does not predict a pass. All ${score.total} items count here.</p><div class="button-row"><a class="button primary" href="#practice/mistakes">Repair my mistakes</a><a class="button" href="#practice/setup">New session</a></div></div></div><div class="domain-results">${score.domains.map(d=>`<section class="panel"><span class="eyebrow">DOMAIN ${d.id}</span><h3>${esc(C.domains.find(x=>x.id===d.id).title)}</h3><b>${d.correct}/${d.total}</b><p class="fine">${d.total?Math.round(d.correct/d.total*100)+'% in this session':'No items in this session'}</p></section>`).join('')}</div><h2>Every answer, explained</h2><div class="results-list">${s.ids.map((id,i)=>{const q=questionMap[id],ok=exact(s.answers[id]||[],q.correct);return `<details class="result-item"><summary><span class="result-icon ${ok?'good':'bad'}">${ok?'✓':'×'}</span><span>${i+1}. ${esc(q.stem)}<small>${(s.answers[id]||[]).length?'Selected '+s.answers[id].length+' option(s)':'Unanswered'} · D${q.domain}</small></span></summary>${explanation(q,s.answers[id]||[])}</details>`;}).join('')}</div>`);}
function tick(){const s=state.session;if(!s||!s.timed||s.done)return;const ms=Math.max(0,s.deadline-Date.now());const el=$('#quiz-timer');if(el){const secs=Math.ceil(ms/1000);el.textContent=Math.floor(secs/60)+':'+String(secs%60).padStart(2,'0');el.classList.toggle('urgent',ms<300000);}if(ms<=0)finishQuiz(true);}
function render(){const [tab,arg]=route();document.querySelectorAll('[data-nav]').forEach(a=>{const current=a.dataset.nav===(tab||'home');a.classList.toggle('active',current);if(current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});switch(tab){case'':case'home':home();break;case'mindmap':$('#app').innerHTML=shell('<div id="mindmap-content"></div>');renderMindMap($('#mindmap-content'),M,C.lessons,arg);break;case'labs':labs(arg);break;case'practice':if(arg==='session')quizSession();else if(arg==='results')quizResults();else quizSetup(arg==='setup'?'all':arg||'all');break;case'glossary':glossary();break;case'route':studyRoute();break;case'reference':references();break;case'notes':notes();break;case'source':source(arg);break;default:learn(arg||state.last);}updateXP();syncUI();}
async function init(){try{[C,Q,G,R,M]=await Promise.all(['course','questions','glossary','reference','mindmap'].map(async f=>{const r=await fetch('./'+f+'.json');if(!r.ok)throw Error('Could not load '+f);return r.json();}));lessonMap=Object.fromEntries(C.lessons.map(l=>[l.id,l]));questionMap=Object.fromEntries(Q.map(q=>[q.id,q]));state=cleanState(state);initUI();render();window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);syncUI({focus:true});});setInterval(tick,1000);registerStudyTools();}catch(err){$('#app').innerHTML=shell(`<div class="empty"><h1>The study content could not load.</h1><p>Please reload this page. Your saved notes remain in this browser.</p><button class="primary" id="retry-load">Try again</button><p class="fine">${esc(err.message)}</p></div>`);$('#retry-load').onclick=()=>location.reload();}}
let toolController;
async function registerStudyTools(){const context=document.modelContext;if(!context?.registerTool)return;toolController=new AbortController();const reply=value=>({content:[{type:'text',text:JSON.stringify(value)}]});try{await context.registerTool({name:'read_study_progress',description:'Read Architect Quest lesson progress, recall reviews and practice performance on this device.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:async()=>reply({read:state.read.length,totalLessons:101,selfRatedRecall:Object.values(state.recall).filter(x=>x.rating==='explain').length,recallDue:recallDue().map(l=>({id:l.id,title:l.title})),mistakeCount:Object.values(state.latest).filter(x=>!x.correct).length,xp:xp()})},{signal:toolController.signal});await context.registerTool({name:'open_study_lesson',description:'Open one of the 101 bilingual lessons by id; ids are l001 through l101.',inputSchema:{type:'object',properties:{lessonId:{type:'string'}},required:['lessonId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async(input)=>{const lessonId=input?.lessonId;if(typeof lessonId!=='string'||!Object.hasOwn(lessonMap,lessonId))return reply({error:'Unknown lesson ID'});location.hash='learn/'+lessonId;render();return reply({opened:lessonId,title:lessonMap[lessonId].title});}},{signal:toolController.signal});window.addEventListener('pagehide',()=>toolController.abort(),{once:true});}catch{/* Progressive enhancement: visible study controls remain fully functional. */}}
init();
